    # For odd length: a1 * a2 * ... * a_mid * ... * a2 * a1 = (a1 * a2 * ... * a_mid)^2 / a_mid
    # For even length: a1 * a2 * ... * ak * ak * ... * a2 * a1 = (a1 * a2 * ... * ak)^2

