    # 2. Check if n is a perfect square (two numbers: a * a)
    # 3. Check if n = a^2 * b where a and b are single digits (three numbers: a * b * a)
    # 4. Check if n = (a * b)^2 (four numbers: a * b * b * a)
    # 5. Check if n = a^2 * b^2 * c (five numbers: a * b * c * b * a)

    # Helper: check if a number is a palindrome
    def is_palindrome(num: int) -> bool:
