from typing import List, Tuple
from functools import lru_cache


def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    """
    Two players play a card game where they remove pairs of cards that match
    either on the front or back. The player who cannot make a move loses.
    Takahashi goes first.

    We use bitmask DP: state is the set of remaining cards.
    A move: pick two cards i, j such that cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1].
    Remove both. The player who cannot make a move loses.

    State: bitmask of remaining cards (n bits).
    f(mask) = True if the current player can win from this state.
    """
    # Precompute: for each pair (i, j), check if they match
    n = len(cards)
    # match[i][j] = True if cards[i] and cards[j] can be paired
    match = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                match[i][j] = match[j][i] = True

    # Use bitmask DP with memoization
    # mask: bits set = cards still present
    # Start with all cards present: (1 << n) - 1

    @lru_cache(maxsize=None)
    def can_win(mask):
        # Find all valid moves: pairs (i, j) where both i and j are in mask and match[i][j]
        # For each move, remove i and j, and check if the opponent loses
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            for j in range(i + 1, n):
                if not (mask & (1 << j)):
                    continue
                if match[i][j]:
                    new_mask = mask ^ (1 << i) ^ (1 << j)
                    if not can_win(new_mask):
                        return True
        return False

    initial_mask = (1 << n) - 1
    if can_win(initial_mask):
        return "Takahashi"
    else:
        return "Aoki"
